func  (this *okx) SafeMarket(optionalArgs ...interface{}) interface{}  {
    marketId := ccxt.GetArg(optionalArgs, 0, nil)
    _ = marketId
    market := ccxt.GetArg(optionalArgs, 1, nil)
    _ = market
    delimiter := ccxt.GetArg(optionalArgs, 2, nil)
    _ = delimiter
    marketType := ccxt.GetArg(optionalArgs, 3, nil)
    _ = marketType
    var isOption interface{} = ccxt.IsTrue((!ccxt.IsEqual(marketId, nil))) && ccxt.IsTrue((ccxt.IsTrue((ccxt.IsGreaterThan(ccxt.GetIndexOf(marketId, "-C"), ccxt.OpNeg(1)))) || ccxt.IsTrue((ccxt.IsGreaterThan(ccxt.GetIndexOf(marketId, "-P"), ccxt.OpNeg(1))))))
    if ccxt.IsTrue(ccxt.IsTrue(isOption) && !ccxt.IsTrue((ccxt.InOp(this.Markets_by_id, marketId)))) {
        // handle expired option contracts
        return this.CreateExpiredOptionMarket(marketId)
    }
    return this.Exchange.SafeMarket(marketId, market, delimiter, marketType)
}
/**
 * @method
 * @name okx#fetchStatus
 * @description the latest known information on the availability of the exchange API
 * @see https://www.okx.com/docs-v5/en/#status-get-status
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [status structure]{@link https://docs.ccxt.com/#/?id=exchange-status-structure}
 */
func  (this *okx) FetchStatus(optionalArgs ...interface{}) <- chan interface{} {
            ch := make(chan interface{})
            go func() interface{} {
                defer close(ch)
                defer ccxt.ReturnPanicError(ch)
                    params := ccxt.GetArg(optionalArgs, 0, map[string]interface{} {})
            _ = params
        
            response:= (<-this.PublicGetSystemStatus(params))
            ccxt.PanicOnError(response)
            //
            // Note, if there is no maintenance around, the 'data' array is empty
            //
            //     {
            //         "code": "0",
            //         "msg": "",
            //         "data": [
            //             {
            //                 "begin": "1621328400000",
            //                 "end": "1621329000000",
            //                 "href": "https://www.okx.com/support/hc/en-us/articles/360060882172",
            //                 "scheDesc": "",
            //                 "serviceType": "1", // 0 WebSocket, 1 Spot/Margin, 2 Futures, 3 Perpetual, 4 ccxt.Options, 5 Trading service
            //                 "state": "scheduled", // ongoing, completed, canceled
            //                 "system": "classic", // classic, unified
            //                 "title": "Classic Spot System Upgrade"
            //             },
            //         ]
            //     }
            //
            var data interface{} = this.SafeList(response, "data", []interface{}{})
            var dataLength interface{} =     ccxt.GetArrayLength(data)
            var update interface{} = map[string]interface{} {
                "updated": nil,
                "status": ccxt.Ternary(ccxt.IsTrue((ccxt.IsEqual(dataLength, 0))), "ok", "maintenance"),
                "eta": nil,
                "url": nil,
                "info": response,
            }
            for i := 0; ccxt.IsLessThan(i, ccxt.GetArrayLength(data)); i++ {
                var event interface{} = ccxt.GetValue(data, i)
                var state interface{} = this.SafeString(event, "state")
                ccxt.AddElementToObject(update, "eta", this.SafeInteger(event, "end"))
                ccxt.AddElementToObject(update, "url", this.SafeString(event, "href"))
                if ccxt.IsTrue(ccxt.IsEqual(state, "ongoing")) {
                    ccxt.AddElementToObject(update, "status", "maintenance")
                } else if ccxt.IsTrue(ccxt.IsEqual(state, "scheduled")) {
                    ccxt.AddElementToObject(update, "status", "ok")
                } else if ccxt.IsTrue(ccxt.IsEqual(state, "completed")) {
                    ccxt.AddElementToObject(update, "status", "ok")
                } else if ccxt.IsTrue(ccxt.IsEqual(state, "canceled")) {
                    ccxt.AddElementToObject(update, "status", "ok")
                }
            }
        
            ch <- update
            return nil
        
            }()
            return ch
        }
