    //      {
    //          "chain": "USDT-Polygon",
    //          "ctAddr": "",
    //          "ccy": "USDT",
    //          "to":"6" ,
    //          "addr": "0x1903441e386cc49d937f6302955b5feb4286dcfa",
    //          "selected": true
    //      }
    // network information from currency['networks'] field:
    // Polygon: {
    //        info: {
    //            canDep: false,
    //            canInternal: false,
    //            canWd: false,
    //            ccy: 'USDT',
    //            chain: 'USDT-Polygon-Bridge',
    //            mainNet: false,
    //            maxFee: '26.879528',
    //            minFee: '13.439764',
    //            minWd: '0.001',
