    //        "posCcy": "",
    //        "posId": "339552508062380036",
    //        "posSide": "long",
    //        "thetaBS": "",
    //        "thetaPA": "",
    //        "tradeId": "98617799",
    //        "uTime": "1627227626502",
    //        "upl": "0.0108608358957281",
    //        "uplRatio": "0.0000636418743944",
    //        "vegaBS": "",
    //        "vegaPA": ""
    //    }
    // history
    //    {
    //        "cTime":"1708351230102",
    //        "ccy":"USDT",
    //        "closeAvgPx":"1.2567",
    //        "closeTotalPos":"40",
    //        "direction":"short",
    //        "fee":"-0.0351036",
    //        "fundingFee":"0",
    //        "instId":"SUSHI-USDT-SWAP",
    //        "instType":"SWAP",
    //        "lever":"10.0",
    //        "liqPenalty":"0",
    //        "mgnMode":"isolated",
    //        "openAvgPx":"1.2462",
    //        "openMaxPos":"40",
    //        "pnl":"-0.42",
    //        "pnlRatio":"-0.0912982667308618",
    //        "posId":"666159086676836352",
    //        "realizedPnl":"-0.4551036",
    //        "triggerPx":"",
    //        "type":"2",
    //        "uTime":"1708354805699",
    //        "uly":"SUSHI-USDT"
    //    }
    //
    market := ccxt.GetArg(optionalArgs, 0, nil)
    _ = market
    var marketId interface{} = this.SafeString(position, "instId")
