func  (this *okx) HandleErrors(httpCode interface{}, reason interface{}, url interface{}, method interface{}, headers interface{}, body interface{}, response interface{}, requestHeaders interface{}, requestBody interface{}) interface{}  {
    if !ccxt.IsTrue(response) {
        return nil  // fallback to default error handler
    }
    //
    //    {
    //        "code": "1",
    //        "data": [
    //            {
    //                "clOrdId": "",
    //                "ordId": "",
    //                "sCode": "51119",
    //                "sMsg": "ccxt.Order placement failed due to insufficient balance. ",
    //                "tag": ""
    //            }
    //        ],
    //        "msg": ""
    //    },
    //    {
    //        "code": "58001",
    //        "data": [],
    //        "msg": "Incorrect trade password"
    //    }
    //
    var code interface{} = this.SafeString(response, "code")
    if ccxt.IsTrue(ccxt.IsTrue((!ccxt.IsEqual(code, "0"))) && ccxt.IsTrue((!ccxt.IsEqual(code, "2")))) {
        var feedback interface{} = ccxt.Add(ccxt.Add(this.Id, " "), body)
        var data interface{} = this.SafeList(response, "data", []interface{}{})
        for i := 0; ccxt.IsLessThan(i, ccxt.GetArrayLength(data)); i++ {
            var err interface{} = ccxt.GetValue(data, i)
            var errorCode interface{} = this.SafeString(err, "sCode")
            var message interface{} = this.SafeString(err, "sMsg")
            this.ThrowExactlyMatchedException(ccxt.GetValue(this.Exceptions, "exact"), errorCode, feedback)
            this.ThrowBroadlyMatchedException(ccxt.GetValue(this.Exceptions, "broad"), message, feedback)
        }
        this.ThrowExactlyMatchedException(ccxt.GetValue(this.Exceptions, "exact"), code, feedback)
        panic(ccxt.ExchangeError(feedback))
    }
    return nil
}
